export const perSegmentShortcut = <V>(value: (index: number) => V) =>
  Object.fromEntries(
    SEGMENT_SHORTCUT_ACTIONS.map((action, index) => [action, value(index)])
  ) as Record<(typeof SEGMENT_SHORTCUT_ACTIONS)[number], V>;

